#!/usr/bin/env bash
# Copyright 2026 Gravity Compile
# SPDX-License-Identifier: Apache-2.0
#
# Vendor audioswitch into the SDK so customers need only Maven Central.
#
# Upstream LiveKit depends on `com.github.davidliu:audioswitch:<commit>`, which exists only on JitPack
# (every app would have to add the JitPack repository). audioswitch is Apache-2.0 (Copyright 2020
# Twilio, inc.); davidliu/audioswitch is LiveKit's fork of twilio/audioswitch.
#
#   tools/vendor/vendor-audioswitch.sh <path-to-davidliu/audioswitch-checkout>
#
# The checkout must be at the commit pinned below (the one upstream v2.28.2 uses). The sources are
# copied to gravix-rtc-android-sdk/src/main/java/com/gravixcloud/rtc/audioswitch/ with the package
# relocated from com.twilio.audioswitch: audioswitch types are part of the SDK's public API
# (AudioSwitchHandler), and an un-relocated copy would produce duplicate classes in any app that
# also uses Twilio's own com.twilio:audioswitch from Maven Central. Re-running replaces the copy.
set -euo pipefail

PIN=039a35aefab7747c557242fa216c9ea11743b604
SRC=${1:?usage: vendor-audioswitch.sh <audioswitch-checkout>}
ROOT=$(git rev-parse --show-toplevel)
COMMIT=$(git -C "$SRC" rev-parse HEAD)
[ "$COMMIT" = "$PIN" ] || { echo "vendor-audioswitch: checkout is at $COMMIT, expected $PIN" >&2; exit 1; }

V_MAJOR=$(sed -n 's/^versionMajor=//p' "$SRC/gradle.properties")
V_MINOR=$(sed -n 's/^versionMinor=//p' "$SRC/gradle.properties")
V_PATCH=$(sed -n 's/^versionPatch=//p' "$SRC/gradle.properties")
VERSION="$V_MAJOR.$V_MINOR.$V_PATCH-${COMMIT:0:7}"

IN="$SRC/audioswitch/src/main/java/com/twilio/audioswitch"
OUT="$ROOT/gravix-rtc-android-sdk/src/main/java/com/gravixcloud/rtc/audioswitch"
rm -rf "$OUT"
mkdir -p "$OUT"

(cd "$IN" && find . -type f \( -name '*.kt' -o -name '*.java' \) | sort) | while IFS= read -r f; do
    f=${f#./}
    mkdir -p "$(dirname "$OUT/$f")"
    {
        echo "// Vendored from https://github.com/davidliu/audioswitch at $COMMIT"
        echo "// (a fork of https://github.com/twilio/audioswitch, version $V_MAJOR.$V_MINOR.$V_PATCH)."
        echo "// Copyright 2020 Twilio, inc. Licensed under the Apache License, Version 2.0;"
        echo "// see third_party/audioswitch/LICENSE.txt."
        echo "// Modifications Copyright 2026 Gravity Compile: package relocated from com.twilio.audioswitch;"
        echo "// BuildConfig.VERSION_NAME replaced by a constant; kapt-safe @VisibleForTesting form. Generated by tools/vendor/vendor-audioswitch.sh."
        echo
        VERSION="$VERSION" perl -pe '
            s/\bcom\.twilio\.audioswitch\b/com.gravixcloud.rtc.audioswitch/g;
            s/\bBuildConfig\.VERSION_NAME\b/"$ENV{VERSION}"/g;
            # kapt (the SDK module runs Dagger through kapt) cannot resolve the statically imported constant
            # in `@VisibleForTesting(otherwise = PRIVATE)` while generating stubs; spell it out (same value).
            s/\(otherwise = PRIVATE\)/(otherwise = VisibleForTesting.PRIVATE)/g;
            # ...and drop that static import: with androidx.annotation 1.7 (the version the SDK uses) VisibleForTesting is a
            # Kotlin annotation whose PRIVATE lives in a companion object, so the import no longer resolves.
            $_ = "" if /^import androidx\.annotation\.VisibleForTesting\.PRIVATE\s*$/;
        ' "$IN/$f"
    } > "$OUT/$f"
done

mkdir -p "$ROOT/third_party/audioswitch"
cp "$SRC/LICENSE.txt" "$ROOT/third_party/audioswitch/LICENSE.txt"
cat > "$ROOT/third_party/audioswitch/README.md" <<EOF
# audioswitch (vendored)

- Source: https://github.com/davidliu/audioswitch at \`$COMMIT\`
  (a fork of https://github.com/twilio/audioswitch; version $V_MAJOR.$V_MINOR.$V_PATCH).
- License: Apache License 2.0, Copyright 2020 Twilio, inc. (\`LICENSE.txt\` here).
- Location in this repository: \`gravix-rtc-android-sdk/src/main/java/com/gravixcloud/rtc/audioswitch/\`.
- Changes: package relocated \`com.twilio.audioswitch\` -> \`com.gravixcloud.rtc.audioswitch\`;
  \`BuildConfig.VERSION_NAME\` replaced by the constant \`"$VERSION"\`; \`@VisibleForTesting(otherwise = PRIVATE)\`
  spelled \`VisibleForTesting.PRIVATE\` (the static import does not resolve against androidx.annotation 1.7); a provenance header added to
  each file. Its manifest permissions (BLUETOOTH up to API 30, MODIFY_AUDIO_SETTINGS) and its keep rule
  are carried by the SDK module's manifest and consumer rules.
- Why: upstream depends on \`com.github.davidliu:audioswitch\`, which is published only on JitPack.
- Regenerate: \`tools/vendor/vendor-audioswitch.sh <checkout at $COMMIT>\`.
EOF

echo "vendor-audioswitch: $(find "$OUT" -type f | wc -l | tr -d ' ') files -> $OUT (version $VERSION)"
